-- V2 catalog migration: 26 Excel rows, preserve historical order-line product IDs.
-- Apply after 001_init.sql and 002_seed.sql via the Supabase SQL editor.
BEGIN;
-- Existing body cream variant aliases must not silently map to Sunday.
WITH offset_value AS (SELECT COALESCE(MAX(display_order),0)+1000 AS n FROM public.products)
UPDATE public.products p SET display_order=p.display_order + o.n FROM offset_value o;
-- Reassign variant-specific historical aliases before deleting ambiguous generic aliases.
UPDATE public.product_aliases SET product_id='default-25' WHERE product_id='default-18' AND label LIKE '%모닝가든%';
DELETE FROM public.product_aliases WHERE product_id='default-18' AND norm_key IN ('바디크림','보타랩바디크림','보타랩바디크림릴랙싱','보타랩바디크림모닝');
-- Bundle decomposition references immutable product IDs, so prior set components remain valid.
COMMIT;
